CREATE TABLE IF NOT EXISTS member_collect (id bigint NOT NULL AUTO_INCREMENT, user_id bigint NOT NULL, spu_id bigint NOT NULL, create_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted bit(1) NOT NULL DEFAULT b'0', PRIMARY KEY(id), UNIQUE KEY uk_user_spu(user_id, spu_id, deleted), KEY idx_user_id(user_id)) ENGINE=InnoDB COMMENT='会员商品收藏表';
CREATE TABLE IF NOT EXISTS member_footprint (id bigint NOT NULL AUTO_INCREMENT, user_id bigint NOT NULL, spu_id bigint NOT NULL, browse_date date NOT NULL, create_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted bit(1) NOT NULL DEFAULT b'0', PRIMARY KEY(id), UNIQUE KEY uk_user_spu_date(user_id, spu_id, browse_date, deleted), KEY idx_user_date(user_id, browse_date)) ENGINE=InnoDB COMMENT='会员浏览足迹表';
CREATE TABLE IF NOT EXISTS product_comment (id bigint NOT NULL AUTO_INCREMENT, user_id bigint NOT NULL, spu_id bigint NOT NULL, content varchar(1000) NOT NULL, status tinyint NOT NULL DEFAULT 1, create_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted bit(1) NOT NULL DEFAULT b'0', PRIMARY KEY(id), KEY idx_spu_time(spu_id, create_time), KEY idx_user_id(user_id)) ENGINE=InnoDB COMMENT='商品评论表';
